#include <iostream>
using namespace std;

void f1(int d[], int n, int x);
int f2(int d[], int a, int b);
int f3(int a, int b, int c);

void f1(int d[], int n, int x)
{
  for(int i=0; i <= n/x; i++){
    d[i] = x*x;
  }
}

int f2(int d[], int a, int b)
{
  int sum = 0;
  for(int i=a; i < b; i++){
    if( d[i] % 2 == 0 ){
      sum += d[i];
    }
  }
  return sum;
}

int f3(int a, int b, int c)
{
  if( a % b == 0) {
    c += 2;
    return b;
  }
  else if( a % c == 0) {
    b -= 1;
    return c;
  }
  return a;
}

